(() => {
'use strict';
const C=window.SPRINT_CONFIG, SNAP=window.SPRINT_SNAPSHOT;
let data=JSON.parse(JSON.stringify(SNAP));
const ui={view:'overview',query:'',owner:'all',kind:'all',group:'all',status:'all',showAll:false,selectedPerson:'EdishAdventure',selectedDay:3,goal:null};
const $=(s,root=document)=>root.querySelector(s);
const $$=(s,root=document)=>Array.from(root.querySelectorAll(s));
const E=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
const icons={user:'<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="4"/>',layout:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',layers:'<path d="m12 2 9 5-9 5-9-5 9-5Z"/><path d="m3 12 9 5 9-5M3 17l9 5 9-5"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>',check:'<path d="m5 12 4 4L19 6"/><rect x="2" y="2" width="20" height="20" rx="5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/>',columns:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M9 3v18M15 3v18"/>',external:'<path d="M14 3h7v7M10 14 21 3"/><path d="M21 13v7a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V4a1 1 0 0 1 1-1h7"/>',github:'<path d="M9 19c-4 1-4-2-6-2m12 5v-3.87a3.37 3.37 0 0 0-.94-2.61c3.14-.35 6.44-1.54 6.44-7A5.44 5.44 0 0 0 19 4.77 5.07 5.07 0 0 0 18.91 1S17.73.65 15 2.48a13.38 13.38 0 0 0-7 0C5.27.65 4.09 1 4.09 1A5.07 5.07 0 0 0 4 4.77 5.44 5.44 0 0 0 2.5 8.52c0 5.42 3.3 6.61 6.44 7A3.37 3.37 0 0 0 8 18.13V22"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',refresh:'<path d="M20 11a8 8 0 0 0-14-5L3 9"/><path d="M3 3v6h6M4 13a8 8 0 0 0 14 5l3-3"/><path d="M15 15h6v6"/>',info:'<circle cx="12" cy="12" r="10"/><path d="M12 11v6M12 7h.01"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',chevron:'<path d="m9 18 6-6-6-6"/>','arrow-up':'<path d="m7 14 5-5 5 5"/>',flag:'<path d="M4 22V4m0 1c7-4 9 4 16 0v12c-7 4-9-4-16 0"/>',circle:'<circle cx="12" cy="12" r="9"/>',sparkles:'<path d="m12 3 1.6 5.4L19 10l-5.4 1.6L12 17l-1.6-5.4L5 10l5.4-1.6L12 3ZM19 17l.7 2.3L22 20l-2.3.7L19 23l-.7-2.3L16 20l2.3-.7L19 17Z"/>',alert:'<path d="M12 3 2 21h20L12 3Z"/><path d="M12 9v5M12 18h.01"/>',file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6M8 13h8M8 17h6"/>',code:'<path d="m8 8-4 4 4 4m8-8 4 4-4 4m-3-13-4 18"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',chart:'<path d="M3 21V3M3 21h18M7 16v-5M12 16V7M17 16V4"/>',close:'<path d="M18 6 6 18M6 6l12 12"/>'};
function icon(name){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.circle}</svg>`}
function person(login){return C.people.find(p=>p.login.toLowerCase()===(login||'').toLowerCase())||{login:login||'',name:login||'Unassigned',full:login||'Unassigned',role:'',color:'#8b96ad',initials:'?'}}
function avatar(login,cls=''){const p=person(login);return `<span class="avatar ${cls}" style="background:${E(p.color)}" aria-label="${E(p.name)}">${E(p.initials)}</span>`}
function item(num){return data.items.find(i=>i.number===num)}
function tasks(){return data.items.filter(i=>i.kind==='task'||i.kind==='acceptance')}
function acceptance(){return data.items.filter(i=>i.kind==='acceptance')}
function completed(i){return i?.state==='closed'}
function countDone(arr){return arr.filter(completed).length}
function progress(group){const t=group.tasks.map(item).filter(Boolean);return {done:countDone(t),total:t.length,pct:t.length?Math.round(countDone(t)/t.length*100):0}}
function friendlyDate(date){if(!date)return '—';const d=new Date(date);return Number.isNaN(d.getTime())?'—':d.toLocaleDateString('en-CA',{month:'short',day:'numeric',timeZone:'America/Toronto'})}
function daysLeft(){const end=new Date('2026-11-16T00:00:00-05:00');return Math.max(0,Math.ceil((end-new Date())/86400000))}
function dateNumber(s){if(!s)return 999;const m=String(s).match(/Nov\s*0?(\d+)/i);return m?Number(m[1]):999}
function chip(label,cl='grey'){return `<span class="chip ${cl}">${E(label)}</span>`}
function cleanTitle(s){return String(s||'').replace(/^\[(?:TASK-\d+|AT-[^\]]+|US-\d+)\]\s*/,'')}
function badgeStatus(i){if(i.kind==='acceptance'&&completed(i)&&i.execution!=='PASS')return chip('Closed · unverified','amber');if(completed(i))return chip('Closed','green');if(i.kind==='acceptance'){const t=(i.execution||'NOT RUN').toUpperCase();return chip(t,t==='PASS'?'green':t==='FAIL'?'red':t==='BLOCKED'?'amber':'amber')}if(i.boardStatus){return chip(i.boardStatus,'blue')}return chip('Open','grey')}
function htmlRunNote(){return data.source==='live'?`Live GitHub snapshot · ${E(friendlyDate(data.capturedAt))}`:'Planning snapshot · GitHub sync not connected'}
function setNotice(message,success=false){const n=$('#notice');n.classList.toggle('hidden',!message);n.classList.toggle('success',success);n.innerHTML=message||''}
function renderPRActivity(){const ps=data.prs||[];return `<div class="panel section"><div class="panel-title-row"><div><h2 class="panel-title">Pull request review queue</h2><div class="panel-subtitle">Open PRs reported by the private GitHub repository</div></div><a class="section-action" href="https://github.com/${E(C.repo)}/pulls" target="_blank" rel="noopener noreferrer">Open PRs ${icon('external')}</a></div>${data.source!=='live'?`<div class="empty-state">${icon('github')}<b>Review queue available with live sync</b>Connect the private GitHub token to show open PRs and reviewers' queue. No sample PRs are fabricated.</div>`:ps.length?`<div class="table-wrap"><table class="issue-table"><thead><tr><th>PULL REQUEST</th><th>AUTHOR</th><th>STATE</th><th>LINK</th></tr></thead><tbody>${ps.map(p=>`<tr><td><div class="issue-title"><span class="issue-code">#${p.number}</span>${E(p.title)}</div></td><td>${E(p.owner)}</td><td>${chip(p.draft?'Draft':'Open',p.draft?'grey':'blue')}</td><td><a target="_blank" rel="noopener noreferrer" href="${E(p.url)}">Review ${icon('external')}</a></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty-state">${icon('check')}<b>No open pull requests</b>The GitHub repository currently reports an empty PR review queue.</div>`}</div>`}
function renderIntro(){return `<div class="info-banner intro-slim">${icon('info')}<div><strong>Feature freeze Nov 12 · final deadline Nov 16.</strong> ${data.source==='live'?'Live GitHub issue status, assignments and verified acceptance evidence.':'Preview uses the Nov 3 GitHub snapshot. Deploy the private Worker to enable real-time sync.'} <button class="text-link" data-sync-help="1">${data.source==='live'?'Sync details':'Connect GitHub'}</button></div></div>`}
// Pace is an estimate from target dates and verified issue outcomes, not effort, hours or a forecast.
function torontoDay(when=new Date()){
  const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Toronto',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(when);
  const values=Object.fromEntries(parts.filter(x=>x.type!=='literal').map(x=>[x.type,x.value]));
  return `${values.year}-${values.month}-${values.day}`;
}
function dateISO(value){
  const day=dateNumber(value);
  return day===999?null:`2026-11-${String(day).padStart(2,'0')}`;
}
function healthAsOf(){return data.source==='live'?torontoDay():torontoDay(new Date(data.capturedAt||C.syncedAt))}
function verifiedDone(issue){if(!completed(issue))return false;if(issue.number===169)return (data.carryoverTests||[]).length===2&&(data.carryoverTests||[]).every(t=>t.state==='closed'&&t.execution==='PASS');return issue.kind!=='acceptance'||(issue.execution||'').toUpperCase()==='PASS'}
function clampSelectedDay(date){
  const day=date.startsWith('2026-11-')?Number(date.slice(8)):date<'2026-11-03'?3:16;
  return Math.max(3,Math.min(16,day));
}
function countHealth(list,asOf=healthAsOf()){
  const scope=list.filter(i=>i.kind==='task'||i.kind==='acceptance');
  const expected=scope.filter(i=>{const due=dateISO(i.due);return due && due<=asOf}).length;
  const actual=scope.filter(verifiedDone).length;
  const overdue=scope.filter(i=>!verifiedDone(i)&&dateISO(i.due)&&dateISO(i.due)<asOf);
  const dueToday=scope.filter(i=>!verifiedDone(i)&&dateISO(i.due)===asOf);
  const soon=scope.filter(i=>{const d=dateISO(i.due);if(!d||verifiedDone(i))return false;const a=new Date(asOf+'T12:00:00-05:00');const b=new Date(d+'T12:00:00-05:00');const days=(b-a)/86400000;return days>0&&days<=2});
  const diff=actual-expected;
  const threshold=Math.max(2,Math.ceil(scope.length*.15));
  let tone='good',label='On track',reason='No missed internal targets';
  if(expected===0&&actual===0){label='On track · early';tone='neutral';reason='No assigned issues due by this date'}
  else if(overdue.length>=2&&diff<=-threshold){label='Behind schedule';tone='bad';reason=`${overdue.length} overdue issues and ${Math.abs(diff)} fewer verified completions than planned`}
  else if(overdue.length){label='At risk';tone='warn';reason=`${overdue.length} overdue assigned issue${overdue.length!==1?'s':''} need attention`}
  else if(diff<0){label='At risk';tone='warn';reason=`${Math.abs(diff)} scheduled item${diff===-1?'':'s'} not yet verified`}
  else if(diff>=2){label='Ahead of schedule';tone='good';reason=`${diff} more verified items than planned by this date`}
  else if(expected===0&&actual>0){label='Ahead of schedule';tone='good';reason='Work closed before the first planned task deadline'}
  return {scope,total:scope.length,expected,actual,diff,overdue,dueToday,soon,tone,label,reason,asOf,plannedPct:scope.length?Math.round(expected/scope.length*100):0,actualPct:scope.length?Math.round(actual/scope.length*100):0};
}
function paceTag(h){return `<span class="pace-tag ${h.tone}"><span class="pace-dot"></span>${E(h.label)}</span>`}
function pacePanel(personLogin=null){
  const mine=personLogin?tasks().filter(i=>i.owner===personLogin):tasks();
  const h=countHealth(mine);
  const asOf=friendlyDate(h.asOf+'T12:00:00-05:00');
  const note=data.source==='live'?'Live GitHub issue states · internal due dates':'Planning snapshot · as of '+asOf+'; not current live status';
  return `<section class="pace-card section" aria-label="Schedule health">
    <div class="pace-heading"><div><div class="eyebrow">DELIVERY PACE · ${E(personLogin?person(personLogin).name.toUpperCase():'TEAM-WIDE')}</div><h2>Are we on schedule?</h2><p>${E(note)}</p></div>${paceTag(h)}</div>
    <div class="pace-main"><div class="pace-bars">
      <div class="pace-bar-title"><span>Planned by ${E(asOf)}</span><strong>${h.expected} / ${h.total} <span>${h.plannedPct}%</span></strong></div>
      <div class="pace-track"><span class="pace-fill planned" style="width:${h.plannedPct}%"></span></div>
      <div class="pace-bar-title"><span>Verified completed</span><strong>${h.actual} / ${h.total} <span>${h.actualPct}%</span></strong></div>
      <div class="pace-track"><span class="pace-fill actual" style="width:${h.actualPct}%"></span></div>
    </div><div class="pace-metrics">
      <div class="pace-delta ${h.diff<0?'negative':h.diff>0?'positive':''}">${h.diff>0?'+':''}${h.diff}<small> items vs plan</small></div>
      <p>${E(h.reason)}. ${h.overdue.length?`<strong>${h.overdue.map(i=>'#'+i.number).slice(0,4).join(', ')}</strong>`:''}</p>
    </div></div>
    <div class="pace-foot"><span>${icon('info')} Equal-weight sub-issues; only closed tasks and acceptance tests marked PASS count as verified.</span><button class="link-inline" data-view="timeline">See daily roadmap ${icon('arrow')}</button></div>
  </section>`;
}
function upcomingFor(list,limit=4){const asOf=healthAsOf();return list.filter(i=>!verifiedDone(i)).sort((a,b)=>dateNumber(a.due)-dateNumber(b.due)||a.number-b.number).slice(0,limit)}
function focusPanel(){
  const today=healthAsOf(); const h=countHealth(tasks()); const next=upcomingFor(tasks(),4);
  const nextM=C.milestones.find(m=>m.iso>=today)||C.milestones[C.milestones.length-1];
  return `<div class="focus-grid section"><div class="panel focus-panel"><div class="panel-title-row"><div><h2 class="panel-title">Next up for the team</h2><div class="panel-subtitle">Prioritized from assigned internal target dates</div></div><button class="link-inline" data-view="mywork">My work ${icon('arrow')}</button></div>
    <div class="focus-list">${next.map(i=>`<button class="focus-row" data-open="${i.number}">${avatar(i.owner,'table-avatar')}<span class="focus-text"><b>${E(cleanTitle(i.title))}</b><small>#${i.number} · ${E(person(i.owner).name)}</small></span><span class="focus-due ${dateISO(i.due)&&dateISO(i.due)<today?'late':''}">${E(i.due)}</span></button>`).join('')}</div></div>
    <div class="panel focus-checkpoint"><div class="panel-title-row"><div><h2 class="panel-title">Next release gate</h2><div class="panel-subtitle">The date to align around</div></div>${icon('flag')}</div><div class="focus-large-date">${E(nextM.date)}</div><h3>${E(nextM.title)}</h3><p>${E(nextM.tag)} · ${h.overdue.length} currently overdue as of ${E(today)}</p><button class="button button-subtle" data-view="timeline">Explore daily plan ${icon('arrow')}</button></div></div>`;
}
function dayItems(day){return tasks().filter(i=>dateNumber(i.due)===day).sort((a,b)=>a.number-b.number)}
function dateInPhase(day,phase){return day>=phase.start&&day<=phase.end}
function dayButton(day){const iso=`2026-11-${String(day).padStart(2,'0')}`;const weekday=new Date(iso+'T12:00:00-05:00').toLocaleDateString('en-US',{weekday:'short',timeZone:'America/Toronto'});
 const due=dayItems(day);const today=torontoDay();return `<button class="roadmap-day ${ui.selectedDay===day?'selected':''} ${today===iso?'is-today':''}" data-day="${day}" aria-pressed="${ui.selectedDay===day}" title="Nov ${day}: ${due.length} internal targets"><span>${E(weekday)}</span><strong>${day}</strong>${due.length?`<i></i>`:''}</button>`;}
function roadmapGraph(){
  return `<div class="roadmap-scroll"><div class="roadmap-inner"><div class="roadmap-header"><div class="roadmap-column-label">SPRINT PHASES</div>${Array.from({length:14},(_,i)=>dayButton(i+3)).join('')}</div>
    ${C.phases.map(ph=>`<div class="roadmap-row"><div class="roadmap-row-name">${E(ph.name)}</div>${Array.from({length:14},(_,i)=>{const day=i+3;return `<button class="roadmap-cell ${dateInPhase(day,ph)?'filled '+ph.id:''} ${ui.selectedDay===day?'selected':''}" data-day="${day}" aria-label="${E(ph.name)} ${E('Nov '+day)} ${dateInPhase(day,ph)?'scheduled':'not scheduled'}"></button>`}).join('')}</div>`).join('')}
    <div class="roadmap-row roadmap-due-row"><div class="roadmap-row-name">Deliverables due</div>${Array.from({length:14},(_,i)=>{const d=i+3, arr=dayItems(d);return `<button class="due-day ${ui.selectedDay===d?'selected':''}" data-day="${d}" aria-label="${arr.length} due on Nov ${d}">${arr.length?arr.length:'·'}</button>`}).join('')}</div></div></div>`;
}
function dayDetails(day){const plan=C.dailyPlan[day],arr=dayItems(day),iso=`2026-11-${String(day).padStart(2,'0')}`;
  const done=arr.filter(verifiedDone).length;
  return `<div class="daily-panel"><div class="daily-head"><div><div class="eyebrow">${E(new Date(iso+'T12:00:00-05:00').toLocaleDateString('en-US',{weekday:'long',timeZone:'America/Toronto'}))} · NOVEMBER ${day}</div><h2>${E(plan.focus)}</h2></div><span class="chip ${arr.length&&done===arr.length?'green':'grey'}">${done}/${arr.length} due items verified</span></div><div class="daily-columns"><div><h3>Planned focus · guidance</h3><ul class="daily-goals">${plan.goals.map(s=>`<li>${E(s)}</li>`).join('')}</ul><div class="note-small">These are planning notes, not interactive checkboxes. Record actual progress in GitHub.</div></div>
    <div><div class="daily-side-title"><h3>GitHub targets for this date</h3><span>${arr.length} due</span></div>${arr.length?`<div class="daily-tasks">${arr.map(i=>`<div class="daily-task"><button class="daily-task-main" data-open="${i.number}"><span class="small-status ${verifiedDone(i)?'finished':'pending'}">${icon(verifiedDone(i)?'check':'clock')}</span><span><b>#${i.number} · ${E(cleanTitle(i.title))}</b><small>${E(person(i.owner).name)} · ${i.kind==='acceptance'?'Acceptance test':'Implementation / QA task'}</small></span></button><a class="progress-action" data-github-update="1" target="_blank" rel="noopener noreferrer" href="${E(i.url)}">Update ${icon('external')}</a></div>`).join('')}</div>`:`<div class="daily-empty">No assigned issue has an internal target date today. Use the planning notes on the left or open the GitHub Project board.</div>`}</div></div></div>`;
}
function dayStripCompact(){const d=clampSelectedDay(healthAsOf());const plan=C.dailyPlan[d];return `<div class="panel compact-roadmap section"><div class="panel-title-row"><div><h2 class="panel-title">Daily sprint roadmap</h2><div class="panel-subtitle">Nov 3–16 · Click a day to explore planned work</div></div><button class="link-inline" data-view="timeline">Full roadmap ${icon('arrow')}</button></div><div class="compact-day-strip">${Array.from({length:14},(_,i)=>{const day=i+3, iso=`2026-11-${String(day).padStart(2,'0')}`;return `<button class="compact-day ${day===d?'selected':''}" data-timeline-day="${day}" aria-label="Open roadmap for November ${day}"><span>${day}</span><i>${dayItems(day).length||'·'}</i></button>`}).join('')}</div><div class="compact-day-note"><span class="status-dot amber"></span><strong>Nov ${d}: ${E(plan.focus)}</strong><span>${E(plan.goals[0])}</span></div></div>`}
function perPersonPanel(login){const p=person(login),mine=tasks().filter(i=>i.owner===login);const h=countHealth(mine);const next=upcomingFor(mine,4);const days=[...new Set(mine.map(i=>dateNumber(i.due)).filter(d=>d!==999))].sort((a,b)=>a-b);
return `<section class="section"><div class="person-banner"><div class="person-banner-main">${avatar(p.login,'profile-avatar')}<div><div class="eyebrow">INDIVIDUAL DELIVERY PLAN</div><h2>${E(p.name)}'s work</h2><p>${E(p.role)}</p></div></div><div class="person-summary-stats"><div><strong>${mine.length}</strong><span>Assigned</span></div><div><strong>${mine.filter(verifiedDone).length}</strong><span>Verified</span></div><div><strong>${h.overdue.length}</strong><span>Overdue</span></div></div></div></section>
${pacePanel(login)}<div class="update-guidance section">${icon('github')}<p><strong>Update progress in GitHub:</strong> Set the task to In Progress, link a PR for review, and close it only after verification. Then click <strong>Sync now</strong> here.</p><a class="progress-action" href="${E(C.projectUrl)}" target="_blank" rel="noopener noreferrer">Open GitHub Project ${icon('external')}</a></div><div class="personal-two-col section"><div class="panel"><div class="panel-title-row"><div><h2 class="panel-title">My next actions</h2><div class="panel-subtitle">Prioritized by upcoming internal due date</div></div>${chip('Issue dates, not clock times','grey')}</div>${next.length?`<div class="focus-list">${next.map(i=>`<div class="focus-row focus-row-linked"><button class="focus-row-main" data-open="${i.number}"><span class="small-status ${verifiedDone(i)?'finished':'pending'}">${icon('clock')}</span><span class="focus-text"><b>${E(cleanTitle(i.title))}</b><small>#${i.number} · ${E(C.groups.find(g=>g.key===i.group)?.id||'Sprint 3')} · ${i.kind==='acceptance'?'Evidence required':'Implementation / QA'}</small></span><span class="focus-due ${dateISO(i.due)&&dateISO(i.due)<healthAsOf()?'late':''}">${E(i.due)}</span></button><a class="progress-action" data-github-update="1" target="_blank" rel="noopener noreferrer" href="${E(i.url)}">Update ${icon('external')}</a></div>`).join('')}</div>`:`<div class="empty-state">${icon('check')}<b>No open tasks in this assignment</b>Check the PR review queue or ask the coordinator for next steps.</div>`}</div>
<div class="panel"><div class="panel-title-row"><div><h2 class="panel-title">My deadline sequence</h2><div class="panel-subtitle">Task ownership from GitHub, dates from sprint plan</div></div></div>${days.length?`<div class="person-deadline-list">${days.map(day=>{const a=mine.filter(i=>dateNumber(i.due)===day),n=a.filter(verifiedDone).length;return `<button class="person-date-row" data-timeline-day="${day}"><span class="person-date-badge">NOV <b>${day}</b></span><span><strong>${a.length} deliverable${a.length!==1?'s':''}</strong><small>${a.slice(0,2).map(i=>'#'+i.number).join(' · ')}${a.length>2?' · …':''}</small></span><span class="person-date-progress">${n}/${a.length}</span></button>`}).join('')}</div>`:'<div class="empty-state">No target dates found.</div>'}</div></div>
<div class="section-header"><div><h2 class="section-title">All of my assigned issues</h2><div class="section-kicker">Open a row to see the GitHub issue details and project status</div></div><button class="section-action" data-view="team">Team comparison ${icon('arrow')}</button></div><div class="panel section" style="padding:0">${renderTable(mine.sort((a,b)=>dateNumber(a.due)-dateNumber(b.due)))}</div>
<div class="mini-banner">${icon('info')}<p>This page uses <b>actual GitHub assignees</b>. Targets are planned dates only; no exact hour was specified. Blockers are only confirmed if GitHub explicitly marks them, or a task is overdue. Keep implementation updates in GitHub, not here.</p></div>`;
}
function renderMyWork(){return `${renderIntro()}<div class="member-switcher section"><div><span>PERSONAL VIEW</span><p>Choose any teammate to see their exact assigned work and deadlines.</p></div><label for="person-select">Viewing <select id="person-select" class="select person-select">${C.people.map(p=>`<option value="${E(p.login)}" ${ui.selectedPerson===p.login?'selected':''}>${E(p.name)}</option>`).join('')}</select></label></div>${perPersonPanel(ui.selectedPerson)}`}

function renderOfficialGoals(){
 return `<section class="section" aria-label="Sprint 3 official outcomes"><div class="section-header"><div><h2 class="section-title">What we must deliver</h2><div class="section-kicker">Four feature areas from the Sprint 3 guidelines · click for assigned work</div></div><span class="chip blue">Official scope</span></div><div class="goals-grid">${C.officialGoals.map(goal=>{const its=C.groups.filter(g=>goal.groups.includes(g.key)).flatMap(g=>g.tasks).map(item).filter(Boolean);const done=its.filter(verifiedDone).length;return `<button class="goal-card" data-official-goal="${E(goal.id)}" aria-label="View tasks for ${E(goal.title)}"><div class="goal-top"><span class="goal-num">${E(goal.num)}</span><span class="goal-steps">${done} / ${its.length} verified</span></div><h3>${E(goal.title)}</h3><p>${E(goal.subtitle)}</p><div class="goal-footer">${avatar(goal.lead,'table-avatar')}<span>${E(person(goal.lead).name)} · lead</span>${icon('arrow')}</div></button>`}).join('')}</div></section>`;
}
function renderOverview(){const t=tasks(),done=countDone(t),at=acceptance();const g=C.groups;const grouped=g.map(x=>({group:x,...progress(x)}));const nearest=[{title:'First integration checkpoint',sub:'First feature PRs reviewed',date:'Nov 07'},{title:'Feature freeze',sub:'Required feature work merged',date:'Nov 12'},{title:'Evidence & release',sub:'Tests, CI, logs and demo',date:'Nov 15'}];return `${renderIntro()}${renderOfficialGoals()}${pacePanel()}${focusPanel()}
<details class="more-details section"><summary>Explore detailed metrics, workstreams and GitHub activity <span>${icon('chevron')}</span></summary><div class="more-body"><div class="grid-4 section"><div class="kpi-card"><div class="kpi-top"><span class="kpi-label">Sub-issues closed</span><span class="kpi-icon">${icon('layers')}</span></div><div class="kpi-value">${done}<small> / ${t.length}</small></div><div class="kpi-foot">${t.length-done} left</div></div><div class="kpi-card"><div class="kpi-top"><span class="kpi-label">New acceptance PASS</span><span class="kpi-icon">${icon('check')}</span></div><div class="kpi-value">${at.filter(i=>verifiedDone(i)).length}<small> / ${at.length}</small></div><div class="kpi-foot">US-04 carryovers separately in Quality</div></div><div class="kpi-card"><div class="kpi-top"><span class="kpi-label">Team members</span><span class="kpi-icon">${icon('users')}</span></div><div class="kpi-value">6</div><div class="kpi-foot">Confirmed GitHub owners</div></div><div class="kpi-card"><div class="kpi-top"><span class="kpi-label">Deadline</span><span class="kpi-icon">${icon('clock')}</span></div><div class="kpi-value">Nov 16</div><div class="kpi-foot">Final evaluation</div></div></div><div class="cols-main section"><div class="panel"><div class="panel-title-row"><div><h2 class="panel-title">Nine delivery workstreams</h2><div class="panel-subtitle">Closed child issues, not estimated effort</div></div><button class="link-inline" data-view="work">All workstreams ${icon('arrow')}</button></div><div class="stream-list">${grouped.map(({group:x,done,total,pct})=>`<div class="stream-item" data-group-open="${E(x.key)}"><span class="stream-stripe" style="background:${E(x.color)}"></span><div><div class="stream-heading">${E(x.short)} <span class="us-tag">${E(x.id)}</span></div><div class="stream-desc">${E(person(x.owner).name)} · ${total} child issues</div><div class="stream-progress"><span style="width:${pct}%;background:${E(x.color)}"></span></div></div><div class="stream-right"><div class="stream-num">${done}/${total}</div><div class="stream-due">${E(x.due)}</div></div></div>`).join('')}</div></div><div class="panel"><div class="panel-title-row"><div><h2 class="panel-title">Release checkpoints</h2><div class="panel-subtitle">Planned internal gates</div></div><button class="link-inline" data-view="timeline">Full timeline ${icon('arrow')}</button></div><div class="delivery-list">${nearest.map((x,i)=>`<div class="delivery-row"><div class="delivery-index">0${i+1}</div><div class="delivery-info"><b>${E(x.title)}</b><span>${E(x.sub)}</span></div><div class="delivery-status">${E(x.date)}</div></div>`).join('')}</div></div></div><div class="panel section"><div class="panel-title-row"><div><h2 class="panel-title">Upcoming work queue</h2><div class="panel-subtitle">Sorted by internal target</div></div><button class="link-inline" data-view="work">Full task list ${icon('arrow')}</button></div>${renderTable(tasks().filter(i=>!completed(i)).sort((a,b)=>dateNumber(a.due)-dateNumber(b.due)).slice(0,7))}</div>${renderPRActivity()}</div></details>`}
function renderTable(rows){if(!rows.length)return `<div class="empty-state">${icon('search')}<b>No matching issues</b>Try another owner, filter or search term.</div>`;return `<div class="table-wrap"><table class="issue-table"><thead><tr><th>ISSUE</th><th>OWNER</th><th>TYPE</th><th>STATUS</th><th>INTERNAL TARGET</th><th>UPDATE</th></tr></thead><tbody>${rows.map(i=>`<tr data-open="${i.number}" tabindex="0" aria-label="View issue ${i.number} details"><td><div class="issue-title"><span class="issue-code">#${i.number}</span>${E(cleanTitle(i.title))}</div></td><td><span style="display:inline-flex;gap:7px;align-items:center">${avatar(i.owner,'table-avatar')}${E(person(i.owner).name)}</span></td><td>${chip(i.kind==='acceptance'?'Acceptance':i.kind==='task'?'Task':i.kind,'grey')}</td><td>${badgeStatus(i)}</td><td>${E(i.due||'Nov 16')}</td><td><a class="progress-action" data-github-update="1" target="_blank" rel="noopener noreferrer" href="${E(i.url)}">Update ${icon('external')}</a></td></tr>`).join('')}</tbody></table></div>`}
function renderWork(){const goalScope=ui.goal?C.officialGoals.find(x=>x.id===ui.goal)?.groups||null:null;const list=C.groups.filter(g=>(!goalScope||goalScope.includes(g.key))&&(ui.group==='all'||g.key===ui.group));const rows=tasks().filter(i=>(!goalScope||goalScope.includes(i.group))&&(ui.owner==='all'||i.owner===ui.owner)&&(ui.kind==='all'||i.kind===ui.kind)&&(ui.status==='all'||(ui.status==='open'&&!completed(i))||(ui.status==='closed'&&completed(i))||(ui.status==='blocked'&&/blocked/i.test(i.boardStatus||''))||(ui.status==='progress'&&/in progress/i.test(i.boardStatus||'')))&&(ui.group==='all'||i.group===ui.group)&&(cleanTitle(i.title)+' '+i.number+' '+person(i.owner).name).toLowerCase().includes(ui.query.toLowerCase())).sort((a,b)=>dateNumber(a.due)-dateNumber(b.due)||a.number-b.number);return `${renderIntro()}<section class="section"><div class="section-header"><div><h2 class="section-title">Feature ownership</h2><div class="section-kicker">Canonical stories and incremental work, no duplicate US numbering</div></div><span class="chip blue">${C.groups.length} workstreams</span></div><div class="stream-grid">${list.map(g=>{const p=progress(g);return `<div class="stream-card" data-group-open="${E(g.key)}"><div class="stream-card-top"><span class="stream-id">${E(g.id)} ${g.id==='US-15'?'· SPRINT 3 INCREMENT':''}</span><span class="stream-category">${E(g.category)}</span></div><h3>${E(g.name)}</h3><p>${E(g.note)}</p><div class="stream-card-progress"><span class="muted">Completed child issues</span><b>${p.done} / ${p.total}</b></div><div class="stream-progress"><span style="width:${p.pct}%;background:${E(g.color)}"></span></div><div class="stream-meta"><div class="stream-owner">${avatar(g.owner)}${E(person(g.owner).name)}</div><span class="stream-date">${E(g.due)}</span></div></div>`}).join('')}</div></section>
<section class="section" id="task-list-section"><div class="section-header"><div><h2 class="section-title">Assigned work queue</h2><div class="section-kicker">${rows.length} matching issues · Click any issue to inspect its details</div></div><a class="section-action" href="${E(C.projectUrl)}" target="_blank" rel="noopener noreferrer">GitHub board ${icon('external')}</a></div><div class="toolbar"><label class="search-wrap">${icon('search')}<input id="work-search" type="search" placeholder="Search issue, number or member…" value="${E(ui.query)}" aria-label="Search tasks"></label><select class="select" id="owner-filter" aria-label="Filter by owner"><option value="all">All owners</option>${C.people.map(p=>`<option value="${E(p.login)}" ${ui.owner===p.login?'selected':''}>${E(p.name)}</option>`).join('')}</select><select class="select" id="kind-filter" aria-label="Filter by type"><option value="all">All types</option><option value="task" ${ui.kind==='task'?'selected':''}>Tasks</option><option value="acceptance" ${ui.kind==='acceptance'?'selected':''}>Acceptance tests</option></select><select class="select" id="status-filter" aria-label="Filter by GitHub status"><option value="all">All statuses</option>${[['open','Open issues'],['closed','Closed issues'],['progress','Board: in progress'],['blocked','Board: blocked']].map(x=>`<option value="${x[0]}" ${ui.status===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></div><div class="panel" style="padding:0">${renderTable(rows)}</div></section>`}
function renderCollaboration(){return `<details class="collab-disclosure section"><summary><span>${icon('users')} How do we work together? <small>5 cross-team handoffs · expand to view</small></span><span class="collab-open">View handoffs ${icon('chevron')}</span></summary><div class="collab-content"><div class="collab-description">These are the key collaboration points suggested by the sprint plan. Actual ownership remains with each GitHub assignee.</div><div class="collab-grid">${C.collaboration.map(c=>`<div class="handoff"><div class="handoff-top"><b>${E(c.feature)}</b><span>${E(c.target)}</span></div><div class="handoff-people"><div>${c.from.map(l=>avatar(l,'table-avatar')).join('')} ${E(c.from.map(l=>person(l).name).join(' / '))}</div><span class="handoff-arrow">${icon('arrow')}</span><div>${c.to.map(l=>avatar(l,'table-avatar')).join('')} ${E(c.to.map(l=>person(l).name).join(' / '))}</div></div><p>${E(c.handoff)}</p></div>`).join('')}</div></div></details>`;}
function renderTeam(){const t=tasks();return `${renderIntro()}<div class="section-header"><div><h2 class="section-title">Who owns what?</h2><div class="section-kicker">Actual GitHub assignments · select anyone for their due-date plan</div></div><span class="chip grey">6 members</span></div><div class="ownership-strip section">${C.people.map(p=>`<button data-member="${E(p.login)}" class="owner-summary">${avatar(p.login)}<span><b>${E(p.name)}</b><small>${E(p.role)}</small></span>${icon('chevron')}</button>`).join('')}</div>${renderCollaboration()}<details class="more-details section"><summary>Full workload, task counts and individual schedule signals <span>${icon('chevron')}</span></summary><div class="more-body"><div class="member-grid">${C.people.map(p=>{const mine=t.filter(i=>i.owner===p.login).sort((a,b)=>dateNumber(a.due)-dateNumber(b.due));const d=countDone(mine),h=countHealth(mine);return `<div class="member-card"><div class="member-head">${avatar(p.login)}<div><h3>${E(p.name)}</h3><small>${E(p.role)}</small></div><div class="member-health">${paceTag(h)}</div></div><div class="member-stat-row"><div class="member-stat"><b>${mine.length}</b><small>Assigned</small></div><div class="member-stat"><b>${d}</b><small>Closed</small></div><div class="member-stat"><b>${h.overdue.length}</b><small>Overdue</small></div></div><div class="stream-progress"><span style="width:${mine.length?d/mine.length*100:0}%;background:${E(p.color)}"></span></div><div class="member-task-list">${mine.slice(0,3).map(i=>`<button class="member-task" data-open="${i.number}"><span>#${i.number} ${E(cleanTitle(i.title))}</span><b>${E(i.due||'—')}</b></button>`).join('')}</div><button class="member-open-btn" data-member="${E(p.login)}">Open ${E(p.name)}’s personal plan ${icon('arrow')}</button></div>`}).join('')}</div><p class="collab-description">Counts represent issues, not work hours or individual grading. Check personal plans for deadlines.</p></div></details>`;}
function renderQuality(){const tests=acceptance().sort((a,b)=>a.number-b.number);return `${renderIntro()}<div class="grid-4 section"><div class="kpi-card"><div class="kpi-top"><span class="kpi-label">New acceptance tests</span><span class="kpi-icon">${icon('check')}</span></div><div class="kpi-value">${tests.length}</div><div class="kpi-foot">Specifications prepared in GitHub</div></div><div class="kpi-card"><div class="kpi-top"><span class="kpi-label">Evidence marked PASS</span><span class="kpi-icon">${icon('flag')}</span></div><div class="kpi-value">${tests.filter(x=>x.execution==='PASS').length}</div><div class="kpi-foot">Require tester, date and actual result</div></div><div class="kpi-card"><div class="kpi-top"><span class="kpi-label">US-04 carryover AT</span><span class="kpi-icon">${icon('file')}</span></div><div class="kpi-value">${(data.carryoverTests||[]).filter(x=>x.state==='closed'&&x.execution==='PASS').length}<small> / 2</small></div><div class="kpi-foot">#107 and #108 · PASS plus closure required</div></div><div class="kpi-card"><div class="kpi-top"><span class="kpi-label">CI status</span><span class="kpi-icon">${icon('code')}</span></div><div class="kpi-value" style="font-size:18px;margin-top:20px">${data.ci?E((data.ci.conclusion||data.ci.status||'unknown').toUpperCase()):'Not synced'}</div><div class="kpi-foot">${data.ci?`Most recent workflow · ${friendlyDate(data.ci.updated_at)}`:'Connect GitHub for latest workflow run'}</div></div></div>
<div class="at-grid section"><div class="panel"><div class="panel-title-row"><div><h2 class="panel-title">Acceptance execution matrix</h2><div class="panel-subtitle">Open a test issue to record real results and evidence</div></div>${chip('Do not infer PASS','amber')}</div><div class="quality-list">${tests.map(i=>`<div class="quality-item" data-open="${i.number}">${avatar(i.owner)}<div class="quality-main"><b>${E(cleanTitle(i.title))}</b><small>#${i.number} · ${E(person(i.owner).name)} · ${E(C.groups.find(g=>g.key===i.group)?.id||'')}</small></div>${badgeStatus(i)}</div>`).join('')}<div class="quality-item" data-open="169">${avatar('EdishAdventure')}<div class="quality-main"><b>US-04 carryover · #107 and #108</b><small>Execute existing profile acceptance specs via TASK-79 #169</small></div>${chip((data.carryoverTests||[]).every(x=>x.state==='closed'&&x.execution==='PASS')?'Verified PASS':'Needs execution',(data.carryoverTests||[]).every(x=>x.state==='closed'&&x.execution==='PASS')?'green':'amber')}</div></div></div>
<div class="panel"><div class="panel-title-row"><div><h2 class="panel-title">Release quality gates</h2><div class="panel-subtitle">Required before the November 15 internal release</div></div></div><div class="release-list">${[{icon:'code',a:'Unit tests & CI',b:'Backend pytest + frontend tests/build on PR and main',num:170},{icon:'check',a:'Executed acceptance tests',b:'Actual PASS/FAIL/BLOCKED, tester, evidence and date',num:169},{icon:'layers',a:'End-to-end regression',b:'Repeatable recruiter/seeker fixtures, edge cases and demo',num:171},{icon:'file',a:'Reporting & individual logs',b:'Meeting minutes, AI logs, 6 PDF reports, one-page summary',num:172}].map(x=>`<div class="release-row" data-open="${x.num}">${icon(x.icon)}<div><strong>${E(x.a)} · #${x.num}</strong><span>${E(x.b)}</span></div></div>`).join('')}</div><div class="mini-banner">${icon('info')}<p>Closing an acceptance-test specification without a recorded execution result is <b>not</b> evidence that it passed. The Sprint 3 report and QA tracker explicitly distinguish written tests from executed tests.</p></div></div></div>`}
function renderTimeline(){const day=ui.selectedDay,h=countHealth(tasks());return `${renderIntro()}<div class="timeline-heading section"><div><span class="eyebrow">NOVEMBER 3–16 · FALL 2026</span><h2>Daily sprint roadmap</h2><p>Click any date to see the planned focus and assigned issues due that day. Highlighted phases may overlap.</p></div><div class="timeline-status">${paceTag(h)}<span>${E(data.source==='live'?'Live GitHub':'Nov 3 planning snapshot')}</span></div></div>
<section class="panel roadmap-shell section"><div class="panel-title-row"><div><h2 class="panel-title">Phase schedule</h2><div class="panel-subtitle">High-level plan · date targets from GitHub tracker #154</div></div><div class="roadmap-legend"><i class="legend-filled"></i>Scheduled phase <i class="legend-dot"></i>Issue target</div></div>${roadmapGraph()}<div class="roadmap-foot"><span>${icon('info')} Blue-outlined day = selected. Vertical day selection does not imply work is done.</span><span>FEATURE FREEZE · NOV 12</span></div></section>
<section class="section">${dayDetails(day)}</section>
<div class="cols-main section"><div class="panel"><div class="panel-title-row"><div><h2 class="panel-title">Release gates</h2><div class="panel-subtitle">Planned checkpoints, not automatically verified achievements</div></div></div><div class="timeline">${C.milestones.map((m,i)=>{const asOf=h.asOf,passed=m.iso<asOf,selected=m.iso===`2026-11-${String(day).padStart(2,'0')}`;return `<div class="timeline-item"><div class="timeline-date">${E(m.date)}</div><div class="timeline-axis"><span class="timeline-dot ${passed?'past':selected?'current':''}"></span>${i<C.milestones.length-1?'<span class="timeline-line"></span>':''}</div><button class="timeline-card ${passed?'past':selected?'current':''}" data-day="${Number(m.iso.slice(-2))}"><b>${E(m.title)}</b><span>${E(m.tag)} · ${passed?'Date passed · verify outcome':'Scheduled'}</span></button></div>`}).join('')}</div></div>
<div class="panel"><div class="panel-title-row"><div><h2 class="panel-title">Schedule variance</h2><div class="panel-subtitle">Planned due issues vs verified completions</div></div></div>${paceTag(h)}<div class="variance-large">${h.diff>0?'+':''}${h.diff} <small>items</small></div><div class="variance-comparison"><span>Expected <b>${h.expected}</b></span><span>Verified <b>${h.actual}</b></span><span>Overdue <b>${h.overdue.length}</b></span></div><div class="mini-banner">${icon('info')}<p>As-of ${E(friendlyDate(h.asOf+'T12:00:00-05:00'))}. Progress uses equal-weight issues, not story points. A written acceptance specification is not a PASS. When viewing the local snapshot, health is <b>historical</b>, not live.</p></div></div></div>`}

function render(){const view=ui.view;$$('[data-view]').forEach(x=>{if(x.classList.contains('nav-link')){x.classList.toggle('active',x.dataset.view===view);x.setAttribute('aria-current',x.dataset.view===view?'page':'false')}});
const labels={overview:['SOEN 341 / TEAM 01','Sprint command center','One place to see what’s moving, what’s blocked, and what must ship.'],work:['SPRINT 3 / DELIVERY','Workstreams & tasks','Canonical GitHub user stories and the work assigned to each teammate.'],team:['SPRINT 3 / PEOPLE','Team workload','A transparent view of ownership, deliverables, and remaining issues.'],mywork:['SPRINT 3 / PERSONAL','My work & deadlines','A date-by-date action plan for every member of the team.'],quality:['SPRINT 3 / VERIFICATION','Quality & release readiness','Track executed acceptance evidence, CI, and final submission obligations.'],timeline:['SPRINT 3 / DAILY ROADMAP','The road to November 16','Visual phases, daily deliverables, and schedule-health signals.']};
const [ey,title,sub]=labels[view]||labels.overview;$('#page-eyebrow').textContent=ey;$('#page-title').innerHTML=E(title)+'<span class="title-dot">.</span>';$('#page-subtitle').textContent=sub;$('#breadcrumb-current').textContent=view==='work'?'Workstreams':view==='quality'?'Quality & tests':view==='mywork'?'My work':view==='team'?'Team capacity':view[0].toUpperCase()+view.slice(1);
$('#source-badge').innerHTML=`<span class="status-dot ${data.source==='live'?'green':'amber'}"></span>${data.source==='live'?'GitHub live':'GitHub snapshot'}`;$('#synced-time').textContent=data.source==='live'?`Updated ${friendlyDate(data.capturedAt)} · auto-refresh`:'Captured Nov 3, 2026';$('#nav-work-count').textContent=tasks().length;$('#view-content').innerHTML=({overview:renderOverview,work:renderWork,team:renderTeam,mywork:renderMyWork,quality:renderQuality,timeline:renderTimeline})[view]();$$('[data-icon]').forEach(n=>n.innerHTML=icon(n.dataset.icon));}

function detail(num){const i=item(Number(num));if(!i)return;const g=C.groups.find(x=>x.key===i.group);const related=i.kind==='story'||i.kind==='tracker'?g?.tasks.map(item).filter(Boolean)||[]:[];const m=$('#detail-panel');m.innerHTML=`<div class="detail-top"><span class="detail-meta">${E(i.kind.toUpperCase())} <span>·</span> ISSUE #${i.number}</span><button class="modal-close" id="modal-close" aria-label="Close issue detail">${icon('close')}</button></div><h2 class="detail-title">${E(cleanTitle(i.title))}</h2><div style="display:flex;gap:6px;flex-wrap:wrap">${badgeStatus(i)} ${chip(i.priority||'P0','blue')} ${chip(g?.id||'Sprint 3','grey')}</div><p class="detail-summary">${E(g?.note||'Sprint 3 implementation and testing deliverable. Check the linked issue for full acceptance criteria, actual evidence, and PR references.')}</p><div class="detail-data"><div><small>Assignee</small><strong style="display:flex;gap:7px;align-items:center">${avatar(i.owner,'table-avatar')} ${E(person(i.owner).name)}</strong></div><div><small>Internal target</small><strong>${E(i.due||'Nov 16')}</strong></div><div><small>GitHub state</small><strong>${E(i.state)}</strong></div><div><small>Project board status</small><strong>${E(i.boardStatus||(data.boardAvailable?'No status set':'Requires Projects access'))}</strong></div></div>${i.kind==='acceptance'?`<div class="info-banner">${icon('info')}<div><strong>Execution: ${E(i.execution||'NOT RUN')}.</strong> The test passes only with actual result, tester, date and evidence recorded in GitHub.</div></div>`:''}${related.length?`<div class="detail-tasks"><h4>Linked Sprint 3 sub-issues (${related.length})</h4>${related.map(x=>`<div class="detail-task" data-open="${x.number}">${icon(completed(x)?'check':'circle')}<b>#${x.number}</b><span>${E(cleanTitle(x.title))}</span></div>`).join('')}</div>`:''}<a class="button button-primary" style="width:100%;margin-top:20px" target="_blank" rel="noopener noreferrer" href="${E(i.url)}">Open issue on GitHub ${icon('external')}</a><div class="note-small" style="margin-top:16px">This dashboard is read-only. Make updates in the GitHub issue or Project board, then synchronize to reflect changes here.</div>`;$('#detail-overlay').classList.remove('hidden');$('#detail-overlay').setAttribute('aria-hidden','false');$('#modal-close').focus();}
function closeDetail(){$('#detail-overlay').classList.add('hidden');$('#detail-overlay').setAttribute('aria-hidden','true')}
function showView(name){ui.view=name;$('#sidebar').classList.remove('open');window.scrollTo({top:0,behavior:'smooth'});render()}
function mergeLive(payload){if(!payload||!Array.isArray(payload.items))throw new Error('Invalid sync response');const byId=new Map(payload.items.map(x=>[Number(x.number),x]));const next=JSON.parse(JSON.stringify(SNAP));for(let i of next.items){const fresh=byId.get(i.number);if(!fresh)continue;i.title=fresh.title||i.title;i.state=fresh.state||i.state;i.owner=fresh.assignees?.[0]||i.owner;i.labels=fresh.labels||i.labels;i.url=fresh.url||i.url;i.updatedAt=fresh.updatedAt||i.updatedAt;i.closedAt=fresh.closedAt||i.closedAt;i.boardStatus=fresh.boardStatus||null;i.execution=fresh.execution||i.execution;if(fresh.due)i.due=fresh.due;}
next.carryoverTests=payload.carryoverTests||next.carryoverTests||[];next.capturedAt=payload.capturedAt||new Date().toISOString();next.prs=payload.prs||[];next.ci=payload.ci||null;next.boardAvailable=!!payload.boardAvailable;next.boardReason=payload.boardReason||null;next.source='live';data=next;render();}
function showSyncHelp(message=''){
const dialog=$('#sync-dialog');const state=$('#sync-detail-status');state.textContent=message|| (data.source==='live'?'GitHub sync is connected. Use “Sync now” to fetch the latest issue states.':'This local preview cannot access private GitHub data directly. The Cloudflare Worker keeps credentials off teammates’ browsers.');
if(!dialog.open)dialog.showModal();
}
async function refresh(manual=false){
const btn=$('#refresh-btn');btn.disabled=true;btn.innerHTML=`${icon('refresh')} Syncing…`;
try{
 if(location.protocol==='file:'){if(manual)showSyncHelp('Standalone HTML is an offline preview. To enable live GitHub sync, deploy the included Worker and access the dashboard on its protected hostname.');return}
 const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),25000);
 let response;try{response=await fetch('/api/overview',{cache:'no-store',signal:controller.signal,headers:{Accept:'application/json'}})}finally{clearTimeout(timer)}
 const body=await response.json().catch(()=>null);
 if(!response.ok){const msg=body?.error||`Server returned ${response.status}`;throw new Error(msg)}
 if(!body?.items||!Array.isArray(body.items))throw new Error('Sync endpoint returned an invalid response');
 mergeLive(body);
 if(manual)setNotice(`Synced from private GitHub at ${E(new Date(body.capturedAt).toLocaleTimeString('en-CA',{hour:'numeric',minute:'2-digit',timeZone:'America/Toronto'}))}. ${body.boardAvailable?'GitHub Project statuses included.':'Issues are live. Project columns require separate read:project access; see the setup guide.'}`,true);
}catch(error){if(manual)showSyncHelp(`Live GitHub sync did not complete: ${error.message}. Check that this site is deployed as a Worker, your GitHub secret is set and Cloudflare Access allows this session.`)}
finally{btn.disabled=false;btn.innerHTML=`${icon('refresh')} Sync now`}
}
function init(){
ui.selectedDay=clampSelectedDay(healthAsOf());
const url='https://github.com/'+C.repo;$('#board-link').href=C.projectUrl;$('#repo-link').href=url;$('#top-issues-link').href=url+'/issues';$('#footer-repo').href=url;
document.addEventListener('click',ev=>{
 const help=ev.target.closest('[data-sync-help]');if(help){ev.preventDefault();showSyncHelp();return}
 const nav=ev.target.closest('[data-view]');if(nav){ev.preventDefault();if(nav.dataset.view==='work'){ui.goal=null;ui.group='all'}showView(nav.dataset.view);return}
 const chosen=ev.target.closest('[data-day]');if(chosen){ui.selectedDay=Number(chosen.dataset.day);showView('timeline');return}
 const compact=ev.target.closest('[data-timeline-day]');if(compact){ui.selectedDay=Number(compact.dataset.timelineDay);showView('timeline');return}
 const mem=ev.target.closest('[data-member]');if(mem){ui.selectedPerson=mem.dataset.member;showView('mywork');return}
 if(ev.target.closest('a[data-github-update]'))return;
 const open=ev.target.closest('[data-open]');if(open){detail(open.dataset.open);return}
 const official=ev.target.closest('[data-official-goal]');if(official){const key=official.dataset.officialGoal;const goal=C.officialGoals.find(x=>x.id===key);if(goal){ui.group=goal.groups.length===1?goal.groups[0]:'all';ui.goal=key;ui.owner='all';ui.query='';ui.kind='all';ui.status='all';showView('work')}return}
 const gr=ev.target.closest('[data-group-open]');if(gr){ui.group=gr.dataset.groupOpen;ui.goal=null;ui.owner='all';ui.query='';ui.kind='all';ui.status='all';showView('work');return}
 const pe=ev.target.closest('[data-person]');if(pe){ui.selectedPerson=pe.dataset.person;showView('mywork');return}
});
$('#refresh-btn').addEventListener('click',()=>refresh(true));
$('#sync-close').addEventListener('click',()=>$('#sync-dialog').close());
$('#sync-copy').addEventListener('click',async()=>{const command='npx wrangler login\nnpx wrangler deploy\nnpx wrangler secret put GITHUB_TOKEN';try{await navigator.clipboard.writeText(command);$('#sync-detail-status').textContent='Deployment commands copied. Follow the README for Cloudflare Access and token permissions.'}catch{showSyncHelp('Copy the commands shown below, then follow the README to protect the private endpoint.')}});
$('#theme-help').addEventListener('click',()=>showSyncHelp('GitHub is the source of truth. Closed issues count as completed; acceptance tests also require a documented PASS. The dashboard never writes to GitHub.'));
$('#mobile-menu').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));
$('#modal-backdrop').addEventListener('click',closeDetail);
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'){closeDetail();$('#sidebar').classList.remove('open')}if((ev.key==='Enter'||ev.key===' ')&&ev.target.matches('tr[data-open]')){ev.preventDefault();detail(ev.target.dataset.open)}});
document.addEventListener('input',ev=>{if(ev.target.id==='work-search'){const sel=ev.target.selectionStart;ui.query=ev.target.value;render();const f=$('#work-search');if(f){f.focus();f.setSelectionRange(sel,sel)}}});
document.addEventListener('change',ev=>{
 if(ev.target.id==='person-select'){ui.selectedPerson=ev.target.value;render()}
 if(ev.target.id==='owner-filter'){ui.owner=ev.target.value;render()}
 if(ev.target.id==='kind-filter'){ui.kind=ev.target.value;render()}
 if(ev.target.id==='status-filter'){ui.status=ev.target.value;render()}
});
render();if(location.protocol!=='file:')refresh(false);
setInterval(()=>{if(data.source==='live')refresh(false)},600000);
}

init();
})();